SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(p),'relation',to_jsonb(pg_identify_object('pg_class'::regclass,p.partrelid,0)),'key',pg_get_partkeydef(p.partrelid)) ORDER BY p.partrelid),'[]'::jsonb) AS payload FROM pg_partitioned_table p WHERE p.partrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture